const customDialog=document.createElement('dialog');customDialog.id='customize-models-dialog';customDialog.innerHTML='<h2>Model customization</h2><label>Model <select id="custom-model"></select></label><label>Custom SVG icon <input id="custom-icon" type="file" accept="image/svg+xml"></label><p class="settings-note">The icon replaces the built-in mark only for the selected model.</p><label>Arena judge <select id="arena-judge"></select></label><p class="settings-note">This model privately chooses Arena’s winning response.</p><div class="custom-actions"><button id="save-customization" type="button">Save changes</button><button id="remove-custom-icon" type="button">Remove icon</button></div><form method="dialog"><button>Done</button></form>';document.body.append(customDialog);
const $custom=s=>customDialog.querySelector(s);let customModels=[],customPreferences={icons:{},arenaJudge:''};async function openCustomization(){const [modelsResponse,prefsResponse]=await Promise.all([fetch('/api/models'),fetch('/api/preferences')]);customModels=await modelsResponse.json();customPreferences=await prefsResponse.json();const installed=customModels.filter(item=>item.installed&&item.id!=='arena');const modelSelect=$custom('#custom-model'),judgeSelect=$custom('#arena-judge');modelSelect.replaceChildren(...installed.map(item=>new Option(item.name,item.id)));judgeSelect.replaceChildren(...installed.map(item=>new Option(item.name,item.id)));judgeSelect.value=installed.some(item=>item.id===customPreferences.arenaJudge)?customPreferences.arenaJudge:installed[0]?.id||'';customDialog.showModal()}
document.querySelector('.model-panel-heading')?.insertAdjacentHTML('beforeend','<button id="customize-models" type="button">Customize</button>');document.addEventListener('click',event=>{if(event.target.id==='customize-models')openCustomization()});$custom('#remove-custom-icon').onclick=()=>{delete customPreferences.icons[$custom('#custom-model').value]};$custom('#save-customization').onclick=async()=>{const input=$custom('#custom-icon'),file=input.files[0];if(file){if(file.type!=='image/svg+xml'){alert('Please choose an SVG file.');return}customPreferences.icons[$custom('#custom-model').value]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})}customPreferences.arenaJudge=$custom('#arena-judge').value;await fetch('/api/preferences',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(customPreferences)});location.reload()};
